import{_ as a,o as t,c as r,a4 as n}from"./chunks/framework.CzJ_HCFe.js";const m=JSON.parse('{"title":"Shantika / Paushtika Source Profile","description":"","frontmatter":{},"headers":[],"relativePath":"reference/42-ceremony-evidence-audit.md","filePath":"reference/42-ceremony-evidence-audit.md","lastUpdated":1788237817000}'),i={name:"reference/42-ceremony-evidence-audit.md"};function o(d,e,s,c,h,u){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="shantika-paushtika-source-profile" tabindex="-1">Shantika / Paushtika Source Profile <a class="header-anchor" href="#shantika-paushtika-source-profile" aria-label="Permalink to &quot;Shantika / Paushtika Source Profile&quot;">​</a></h1><h2 id="scope-and-authority" tabindex="-1">Scope and authority <a class="header-anchor" href="#scope-and-authority" aria-label="Permalink to &quot;Scope and authority&quot;">​</a></h2><p>The <code>ceremony</code> compatibility key now names a <strong>Shantika / Paushtika rite</strong> and links to verified claim <code>muhurta.shantika_paushtika</code>. It is not a generic election for every ceremony or Puja.</p><p>The source is Rama Daivajna, <em>Muhurta Chintamani</em>, undated Sanskrit text with Hindi commentary, Nakshatra-prakarana, “Shantika and Paushtika Muhurta,” verse 34, printed pages 42–43 (Internet Archive OCR lines 2749–2772). The scan lacks publisher and date metadata, which the source register discloses.</p><h2 id="exact-crosswalk" tabindex="-1">Exact crosswalk <a class="header-anchor" href="#exact-crosswalk" aria-label="Permalink to &quot;Exact crosswalk&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source criterion</th><th>Implementation</th><th>Boundary</th></tr></thead><tbody><tr><td>Reject Rikta, Ashtami, Pournami and Amavasya</td><td><code>avoid_tithi_numbers = [4, 8, 9, 14, 15]</code></td><td>15 covers both lunar termini</td></tr><tr><td>Reject Sunday, Tuesday and Saturday</td><td>Four-day <code>allowed_varas</code></td><td>Hard day gate</td></tr><tr><td>Fifteen named Nakshatras</td><td>Exact <code>allowed_nakshatras</code></td><td>Hard day gate</td></tr><tr><td>Reject Sankramana</td><td><code>skip_on_sankramana = true</code></td><td>Hard day gate</td></tr><tr><td>Surya in the 10th, Chandra in the 4th, Guru in Lagna</td><td><code>ELECTION_CHART_RULES[ceremony]</code></td><td>Three independent Drik browser tie-break preferences, counted only across every sampled state (edges and both sides of known interior Lagna transitions); <code>manual_prerequisites = true</code> still caps unresolved review below Excellent</td></tr><tr><td>Ideally avoid Guru/Shukra combustion and exceptional omens</td><td>Manual purity check</td><td>Not uniformly computable across all surfaces</td></tr></tbody></table><p>The passage&#39;s examples are auspicious Puja, welfare-oriented Purashcharana and Mula-shanti. Those examples do not authorize a universal “ceremony” profile.</p><p>Python/MCP retain the chart wording as <code>manual_checks</code>; only the Drik browser requests candidate-time charts. Combustion, exceptional omens, ritual scope and the remedial exception remain practitioner judgments. See <a href="./54-muhurtam-election-chart-screening">Muhurtam election-chart screening</a>.</p><h2 id="remedial-exception" tabindex="-1">Remedial exception <a class="header-anchor" href="#remedial-exception" aria-label="Permalink to &quot;Remedial exception&quot;">​</a></h2><p>The commentary says that when an ominous event itself creates the need for Shanti, ordinary timing defects need not prevent the remedial rite. The finder therefore must not be used to delay an urgent Shanti; the officiating practitioner determines how the exception applies.</p>',10)])])}const p=a(i,[["render",o]]);export{m as __pageData,p as default};
